def color_enabled(opts: Opts) -> bool:
    if opts.color == 'always':
        return True
    if opts.color == 'never':
        return False
    return sys.stdout.isatty()

def cwrap(text, code, enabled):
    return f"\033[{code}m{text}\033[0m" if enabled else text

def color_target(src_base, tgt_base, enabled):
    if not enabled:
        return tgt_base
    sm = difflib.SequenceMatcher(a=src_base, b=tgt_base)
    parts = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        seg = tgt_base[j1:j2]
        if not seg:
            continue
        if tag == 'equal':
            parts.append(cwrap(seg, '32', True))
        else:
            parts.append(cwrap(seg, '1;31', True))
    return ''.join(parts)

def print_op(op: Operation, opts: Opts):
    if opts.silent:
        return
    en = color_enabled(opts)
    if not en:
        print(f"{op.source} -> {op.target}")
        return
    src = cwrap(op.source, '38;5;8', True)
    # Color the target filename using the source filename as a diff base.
    src_dir, src_base = os.path.split(op.source)
    tgt_dir, tgt_base = os.path.split(op.target)
    colored_base = color_target(src_base, tgt_base, True)
    target = (tgt_dir + os.sep if tgt_dir else '') + colored_base
    print(f"{src} -> {target}")

def print_dry(opts: Opts):
    if not opts.silent:
        print(cwrap("This is a DRY-RUN", '1', color_enabled(opts)))

