def ascii_transliterate(s: str) -> str:
    out = []
    for ch in s:
        if ord(ch) < 128:
            out.append(ch)
            continue
        if ch in CHARMAP:
            out.append(CHARMAP[ch])
            continue
        decomp = unicodedata.normalize('NFKD', ch)
        piece = []
        for c in decomp:
            if unicodedata.combining(c):
                continue
            if ord(c) < 128:
                piece.append(c)
            elif c in CHARMAP:
                piece.append(CHARMAP[c])
        if piece:
            out.append(''.join(piece))
        else:
            # Drop unknown symbols, matching the spirit of the original transliterator.
            pass
    return ''.join(out)

def eprint(s=""):
    print(s, file=sys.stderr)

def color_enabled(opts: Opts) -> bool:
    if opts.color == 'always':
        return True
    if opts.color == 'never':
        return False
    return sys.stdout.isatty()

def cwrap(text, code, enabled):
    return f"\033[{code}m{text}\033[0m" if enabled else text

def color_target(src_base, tgt_base, enabled):
    if not enabled:
        return tgt_base
    sm = difflib.SequenceMatcher(a=src_base, b=tgt_base)
    parts = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        seg = tgt_base[j1:j2]
        if not seg:
            continue
        if tag == 'equal':
            parts.append(cwrap(seg, '32', True))
        else:
            parts.append(cwrap(seg, '1;31', True))
    return ''.join(parts)

def print_op(op: Operation, opts: Opts):
    if opts.silent:
        return
    en = color_enabled(opts)
    if not en:
        print(f"{op.source} -> {op.target}")
        return
    src = cwrap(op.source, '38;5;8', True)
    # Color the target filename using the source filename as a diff base.
    src_dir, src_base = os.path.split(op.source)
    tgt_dir, tgt_base = os.path.split(op.target)
    colored_base = color_target(src_base, tgt_base, True)
    target = (tgt_dir + os.sep if tgt_dir else '') + colored_base
    print(f"{src} -> {target}")

def print_dry(opts: Opts):
    if not opts.silent:
        print(cwrap("This is a DRY-RUN", '1', color_enabled(opts)))

def error_msg(msg, opts: Opts | None = None):
    if opts is not None and color_enabled(opts):
        eprint(cwrap("Error: ", '31', True) + msg)
    else:
        eprint("Error: " + msg)

def parse_int_value(val, optname):
    if not val.isdigit():
        eprint(f"error: invalid value '{val}' for '{optname}': invalid digit found in string\n")
        eprint("For more information, try '--help'.")
        sys.exit(2)
    return int(val)

def require_value(args, i, flag):
    if i + 1 >= len(args):
        eprint(f"error: a value is required for '{flag} <{flag.lstrip('-').upper()}>' but none was supplied\n")
        eprint("For more information, try '--help'.")
        sys.exit(2)
    return args[i+1], i+1

def parse_options(cmd, args):
    opts = Opts()
    pos = []
    i = 0
    while i < len(args):
        a = args[i]
        if a == '--':
            pos.extend(args[i+1:]); break
        if a in ('-n','--dry-run'):
            opts.dry_flag = True
        elif a in ('-f','--force'):
            opts.force = True
        elif a in ('-b','--backup'):
            opts.backup = True
        elif a in ('-s','--silent'):
            opts.silent = True
        elif a == '--color':
            val, i = require_value(args, i, '--color')
            if val not in ('always','never','auto'):
                eprint(f"error: invalid value '{val}' for '--color <COLOR>'")
                eprint("  [possible values: always, never, auto]\n")
                eprint("For more information, try '--help'.")
                sys.exit(2)
            opts.color = val
        elif a.startswith('--color='):
            val = a.split('=',1)[1]
            if val not in ('always','never','auto'):
                eprint(f"error: invalid value '{val}' for '--color <COLOR>'")
                eprint("  [possible values: always, never, auto]\n")
                eprint("For more information, try '--help'.")
                sys.exit(2)
            opts.color = val
        elif a == '--dump':
            opts.dump = True
        elif a == '--no-dump':
            opts.no_dump = True
        elif a == '--dump-prefix':
            val, i = require_value(args, i, '--dump-prefix')
            opts.dump_prefix = val
        elif a.startswith('--dump-prefix='):
            opts.dump_prefix = a.split('=',1)[1]
        elif cmd in ('regex','to-ascii') and a in ('-D','--include-dirs'):
            opts.include_dirs = True
        elif cmd in ('regex','to-ascii') and a in ('-r','--recursive'):
            opts.recursive = True
        elif cmd in ('regex','to-ascii') and a in ('-x','--hidden'):
            opts.hidden = True
        elif cmd in ('regex','to-ascii') and a in ('-d','--max-depth'):
            val, i = require_value(args, i, '--max-depth')
            opts.max_depth = parse_int_value(val, '--max-depth <LEVEL>')
        elif cmd == 'regex' and a in ('-l','--replace-limit'):
            val, i = require_value(args, i, '--replace-limit')
            opts.replace_limit = parse_int_value(val, '--replace-limit <LIMIT>')
        elif cmd == 'regex' and a in ('-t','--replace-transform'):
            val, i = require_value(args, i, '--replace-transform')
            if val not in ('upper','lower','ascii'):
                eprint(f"error: invalid value '{val}' for '--replace-transform <REPLACE_TRANSFORM>'")
                eprint("  [possible values: upper, lower, ascii]\n")
                eprint("For more information, try '--help'.")
                sys.exit(2)
            opts.transform = val
        elif cmd == 'from-file' and a in ('-u','--undo'):
            opts.undo = True
        elif a.startswith('-') and a != '-':
            eprint(f"error: unexpected argument '{a}' found\n")
            eprint("For more information, try '--help'.")
            sys.exit(2)
        else:
            pos.append(a)
        i += 1
    if opts.force and opts.dry_flag:
        eprint(f"error: the argument '--force' cannot be used with '--dry-run'\n")
        eprint(f"Usage: executable {cmd} --force " + ("<EXPRESSION> <REPLACEMENT> <PATH(S)>..." if cmd=='regex' else ("<DUMPFILE>" if cmd=='from-file' else "<PATH(S)>...")) + "\n")
        eprint("For more information, try '--help'.")
        sys.exit(2)
    if opts.dump and opts.no_dump:
        eprint(f"error: the argument '--dump' cannot be used with '--no-dump'\n")
        eprint(f"Usage: executable {cmd} --dump " + ("<EXPRESSION> <REPLACEMENT> <PATH(S)>..." if cmd=='regex' else ("<DUMPFILE>" if cmd=='from-file' else "<PATH(S)>...")) + "\n")
        eprint("For more information, try '--help'.")
        sys.exit(2)
    return opts, pos

def is_actual(opts: Opts):
    return opts.force

def should_dump(opts: Opts):
    if opts.no_dump:
        return False
    return opts.dump or opts.force

def dump_ops(ops, prefix):
    now = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    fname = prefix + datetime.datetime.now().strftime('%Y-%m-%d_%H%M%S') + '.json'
    data = {'date': now, 'operations': [{'source': op.source, 'target': op.target} for op in ops]}
    txt = json.dumps(data, indent=2, ensure_ascii=False)
    with open(fname, 'w', encoding='utf-8') as f:
        f.write(txt)

def backup_path(path):
    base = path + '.bk'
    if not os.path.exists(base) and not os.path.lexists(base):
        return base
    n = 1
    while True:
        cand = base + f'.{n}'
        if not os.path.exists(cand) and not os.path.lexists(cand):
            return cand
        n += 1

def make_backup(path, opts):
    b = backup_path(path)
    try:
        if os.path.isdir(path) and not os.path.islink(path):
            shutil.copytree(path, b, symlinks=True)
        else:
            shutil.copy2(path, b, follow_symlinks=False)
    except Exception:
        return
    if not opts.silent:
        en = color_enabled(opts)
        if en:
            print(cwrap('Info: ', '1', True) + ' Backup created - ' + cwrap(f'{path} -> {b}', '38;5;8', True))
        else:
            print(f"Info:  Backup created - {path} -> {b}")

def execute_ops(ops, opts: Opts, prevalidated=True):
    if not opts.force:
        for op in ops:
            print_op(op, opts)
        if should_dump(opts):
            dump_ops(ops, opts.dump_prefix)
        return 0
    completed = []
    for op in ops:
        if opts.backup:
            make_backup(op.source, opts)
        try:
            os.rename(op.source, op.target)
        except OSError as e:
            error_msg(f"Cannot rename {op.source} -> {op.target}\n{e.strerror} (os error {e.errno})", opts)
            return 1
        completed.append(op)
        print_op(op, opts)
    if should_dump(opts):
        dump_ops(ops, opts.dump_prefix)
    return 0

def validate_ops(ops, opts: Opts):
    # Duplicate target names among computed operations.
    by_t = {}
    for op in ops:
        by_t.setdefault(op.target, []).append(op)
    for target, group in by_t.items():
        if len(group) > 1:
            error_msg("Files will have the same name\n", opts)
            # The original prints compact source->target lines on stderr.
            for op in sorted(group, key=lambda o: o.source):
                eprint(f"{op.source}->{op.target}")
            eprint("")
            return 1
    for op in ops:
        if op.source != op.target and (os.path.exists(op.target) or os.path.lexists(op.target)):
            if color_enabled(opts):
                eprint(cwrap('Error: ', '31', True) + 'Conflict with existing path ' + cwrap(f'{op.source} -> {op.target}', '31', True))
            else:
                eprint(f"Error: Conflict with existing path {op.source} -> {op.target}")
            return 1
    return 0

def rust_regex_to_python(expr):
    # Rust regex accepts (?<name>...) whereas Python wants (?P<name>...).
    return re.sub(r'\(\?<([A-Za-z_][A-Za-z0-9_]*)>', r'(?P<\1>', expr)

def expand_replacement(rep, m):
    out = []
    i = 0
    while i < len(rep):
        ch = rep[i]
        if ch != '$':
            out.append(ch); i += 1; continue
        if i + 1 < len(rep) and rep[i+1] == '$':
            out.append('$'); i += 2; continue
        if i + 1 < len(rep) and rep[i+1] == '{':
            j = rep.find('}', i+2)
            if j != -1:
                name = rep[i+2:j]
                out.append(group_value(m, name))
                i = j + 1
                continue
        j = i + 1
        while j < len(rep) and (rep[j].isalnum() or rep[j] == '_'):
            j += 1
        if j > i + 1:
            name = rep[i+1:j]
            out.append(group_value(m, name))
            i = j
        else:
            out.append('$'); i += 1
    return ''.join(out)

def group_value(m, name):
    try:
        if name.isdigit():
            idx = int(name)
            val = m.group(idx)
        else:
            val = m.group(name)
        return val or ''
    except Exception:
        return ''

def apply_transform(s, transform):
    if transform == 'upper':
        return s.upper()
    if transform == 'lower':
        return s.lower()
    if transform == 'ascii':
        return ascii_transliterate(s)
    return s

def regex_rename_basename(basename, cre, replacement, opts):
    count = 1 if opts.replace_limit is None else opts.replace_limit
    # Python count=0 means all, same as observed --replace-limit 0.
    def repl(m):
        return apply_transform(expand_replacement(replacement, m), opts.transform)
    return cre.sub(repl, basename, count=count)

def split_target_path(path):
    d, b = os.path.split(path)
    return d, b

def path_join_preserve(d, b):
    return os.path.join(d, b) if d else b

def op_for_path(path, renamer):
    d, b = split_target_path(path)
    if b == '':
        return None
    nb = renamer(b)
    if nb == b:
        return None
    return Operation(path, path_join_preserve(d, nb))

def hidden_name(path):
    return os.path.basename(path).startswith('.')

def collect_paths(targets, opts: Opts):
    result = []  # list of (path, is_dirish)
    for t in targets:
        if not os.path.lexists(t):
            continue
        isdir = os.path.isdir(t) and not os.path.islink(t)
        if isdir:
            if opts.recursive:
                # Bottom-up traversal so contained files/directories are renamed before parents.
                for root, dirs, files in os.walk(t, topdown=False, followlinks=False):
                    # Determine depth of entries relative to t: children of t are depth 1.
                    relroot = os.path.relpath(root, t)
                    root_depth = 0 if relroot == '.' else relroot.count(os.sep) + 1
                    # Files and symlinked dirs at this level.
                    file_names = list(files)
                    symlink_dirs = []
                    for dn in dirs:
                        p = os.path.join(root, dn)
                        if os.path.islink(p):
                            symlink_dirs.append(dn)
                    for fn in file_names:
                        if not opts.hidden and fn.startswith('.'):
                            continue
                        depth = root_depth + 1
                        if opts.max_depth is not None and depth > opts.max_depth:
                            continue
                        result.append(os.path.join(root, fn))
                    if opts.include_dirs:
                        for dn in symlink_dirs + list(dirs):
                            if not opts.hidden and dn.startswith('.'):
                                continue
                            p = os.path.join(root, dn)
                            depth = root_depth + 1
                            if opts.max_depth is not None and depth > opts.max_depth:
                                continue
                            result.append(p)
                if opts.include_dirs:
                    if opts.max_depth is None or opts.max_depth >= 0:
                        result.append(t)
            else:
                if opts.include_dirs:
                    result.append(t)
        else:
            result.append(t)
    # Remove exact duplicate source paths while preserving first occurrence.
    seen = set(); out = []
    for p in result:
        if p not in seen:
            seen.add(p); out.append(p)
    return out

def generate_regex_ops(expr, replacement, targets, opts):
    try:
        cre = re.compile(rust_regex_to_python(expr))
    except re.error as e:
        eprint("Error: Bad expression provided\n")
        eprint(str(e))
        return None
    paths = collect_paths(targets, opts)
    ops = []
    for p in paths:
        op = op_for_path(p, lambda b: regex_rename_basename(b, cre, replacement, opts))
        if op:
            ops.append(op)
    return ops

def generate_ascii_ops(targets, opts):
    paths = collect_paths(targets, opts)
    ops = []
    for p in paths:
        op = op_for_path(p, ascii_transliterate)
        if op:
            ops.append(op)
    return ops

def handle_regex(args):
    if not args:
        eprint(REGEX_HELP); return 2
    if '-h' in args or '--help' in args:
        print(REGEX_HELP); return 0
    opts, pos = parse_options('regex', args)
    if len(pos) < 2:
        missing = []
        if len(pos) < 1: missing.append('  <EXPRESSION>')
        if len(pos) < 2: missing.append('  <REPLACEMENT>')
        missing.append('  <PATH(S)>...')
        eprint('error: the following required arguments were not provided:')
        eprint('\n'.join(missing) + '\n')
        eprint('Usage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n')
        eprint("For more information, try '--help'.")
        return 2
    if len(pos) < 3:
        eprint('error: the following required arguments were not provided:')
        eprint('  <PATH(S)>...\n')
        eprint('Usage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n')
        eprint("For more information, try '--help'.")
        return 2
    ops = generate_regex_ops(pos[0], pos[1], pos[2:], opts)
    if ops is None:
        return 1
    if not opts.force:
        print_dry(opts)
    rc = validate_ops(ops, opts)
    if rc:
        return rc
    return execute_ops(ops, opts)

def handle_ascii(args):
    if not args:
        eprint(ASCII_HELP); return 2
    if '-h' in args or '--help' in args:
        print(ASCII_HELP); return 0
    opts, pos = parse_options('to-ascii', args)
    if len(pos) < 1:
        eprint(ASCII_HELP); return 2
    ops = generate_ascii_ops(pos, opts)
    if not opts.force:
        print_dry(opts)
    rc = validate_ops(ops, opts)
    if rc:
        return rc
    return execute_ops(ops, opts)

def parse_dump_file(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except FileNotFoundError:
        return 'open', None
    except Exception:
        return 'parse', None
    try:
        if not isinstance(data, dict) or 'date' not in data or not isinstance(data.get('date'), str):
            raise ValueError
        ops_raw = data['operations']
        if not isinstance(ops_raw, list):
            raise ValueError
        ops = []
        for o in ops_raw:
            if not isinstance(o, dict) or not isinstance(o.get('source'), str) or not isinstance(o.get('target'), str):
                raise ValueError
            ops.append(Operation(o['source'], o['target']))
        return None, ops
    except Exception:
        return 'parse', None

def handle_from(args):
    if not args:
        eprint(FROM_HELP); return 2
    if '-h' in args or '--help' in args:
        print(FROM_HELP); return 0
    opts, pos = parse_options('from-file', args)
    if len(pos) < 1:
        eprint(FROM_HELP); return 2
    dumpfile = pos[0]
    if not opts.force:
        print_dry(opts)
    err, ops = parse_dump_file(dumpfile)
    if err == 'open':
        error_msg(f"Cannot open/read file {dumpfile}", opts); return 1
    if err == 'parse':
        error_msg(f"Cannot parse JSON file {dumpfile}", opts); return 1
    if opts.undo:
        ops = [Operation(o.target, o.source) for o in reversed(ops)]
    # Observed from-file does not pre-validate conflicts; it delegates to rename.
    return execute_ops(ops, opts, prevalidated=False)

def main(argv):
    if not argv:
        print(TOP_HELP); return 2
    if argv[0] in ('-h','--help'):
        print(TOP_HELP); return 0
    if argv[0] in ('-V','--version'):
        print(VERSION); return 0
    if argv[0] == 'help':
        if len(argv) >= 2:
            if argv[1] == 'regex': print(REGEX_HELP); return 0
            if argv[1] == 'from-file': print(FROM_HELP); return 0
            if argv[1] == 'to-ascii': print(ASCII_HELP); return 0
        print(TOP_HELP); return 0
    cmd = argv[0]
    if cmd == 'regex':
        return handle_regex(argv[1:])
    if cmd == 'from-file':
        return handle_from(argv[1:])
    if cmd == 'to-ascii':
        return handle_ascii(argv[1:])
    eprint(f"error: unrecognized subcommand '{cmd}'\n")
    eprint("Usage: executable <COMMAND>\n")
    eprint("For more information, try '--help'.")
    return 2

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
